<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import type { ColDef } from 'ag-grid-community'
import { ElMessage, ElMessageBox } from 'element-plus'
import AppDataGrid from '@/components/AppDataGrid.vue'
import { applyKubernetesObject, deleteKubernetesObject, getKubernetesObject, listKubernetesClusters, listKubernetesObjects, type KubernetesCluster, type KubernetesObject } from '@/api/kubernetes'

const groups: Record<string, { label:string; resources:{key:string;label:string;namespaced:boolean}[] }> = {
  network: { label:'网络管理', resources:[{key:'services',label:'Service',namespaced:true},{key:'ingresses',label:'Ingress',namespaced:true},{key:'endpoints',label:'Endpoints',namespaced:true},{key:'networkpolicies',label:'NetworkPolicy',namespaced:true}] },
  config: { label:'配置管理', resources:[{key:'configmaps',label:'ConfigMap',namespaced:true},{key:'secrets',label:'Secret',namespaced:true},{key:'resourcequotas',label:'ResourceQuota',namespaced:true},{key:'limitranges',label:'LimitRange',namespaced:true},{key:'horizontalpodautoscalers',label:'HPA',namespaced:true},{key:'poddisruptionbudgets',label:'PDB',namespaced:true}] },
  storage: { label:'存储管理', resources:[{key:'persistentvolumeclaims',label:'PVC',namespaced:true},{key:'persistentvolumes',label:'PV',namespaced:false},{key:'storageclasses',label:'StorageClass',namespaced:false}] },
  access: { label:'访问控制', resources:[{key:'serviceaccounts',label:'ServiceAccount',namespaced:true},{key:'roles',label:'Role',namespaced:true},{key:'rolebindings',label:'RoleBinding',namespaced:true},{key:'clusterroles',label:'ClusterRole',namespaced:false},{key:'clusterrolebindings',label:'ClusterRoleBinding',namespaced:false}] },
  workloads: { label:'工作负载管理', resources:[{key:'deployments',label:'Deployment',namespaced:true},{key:'statefulsets',label:'StatefulSet',namespaced:true},{key:'daemonsets',label:'DaemonSet',namespaced:true},{key:'jobs',label:'Job',namespaced:true},{key:'cronjobs',label:'CronJob',namespaced:true},{key:'pods',label:'Pod',namespaced:true}] },
  namespaces: { label:'命名空间', resources:[{key:'namespaces',label:'Namespace',namespaced:false}] },
}
const route=useRoute(), group=computed(()=>groups[String(route.meta.kubernetesGroup)] || groups.network)
const clusters=ref<KubernetesCluster[]>([]), clusterID=ref(0), resource=ref(''), namespace=ref(''), keyword=ref(''), rows=ref<KubernetesObject[]>([]), dialog=ref(false), yaml=ref('')
const current=computed(()=>group.value.resources.find(x=>x.key===resource.value) || group.value.resources[0])
async function loadClusters(){const {data}=await listKubernetesClusters();clusters.value=data.data;const queryID=Number(route.query.cluster_id||0);if(queryID&&clusters.value.some(x=>x.id===queryID))clusterID.value=queryID;else if(!clusterID.value&&clusters.value[0])clusterID.value=clusters.value[0].id}
async function load(){if(!clusterID.value)return rows.value=[];const {data}=await listKubernetesObjects({cluster_id:clusterID.value,resource:resource.value,namespace:namespace.value,keyword:keyword.value});rows.value=data.data}
async function edit(row?:KubernetesObject){if(row){const {data}=await getKubernetesObject({cluster_id:clusterID.value,resource:resource.value,namespace:row.namespace,name:row.name});yaml.value=data.data.yaml}else{yaml.value=`apiVersion: v1\nkind: ${current.value.label}\nmetadata:\n  name: example\n${current.value.namespaced?'  namespace: default\n':''}`};dialog.value=true}
async function save(){await applyKubernetesObject({cluster_id:clusterID.value,resource:resource.value,namespace:namespace.value,yaml:yaml.value});dialog.value=false;ElMessage.success('保存成功');load()}
async function remove(row:KubernetesObject){await ElMessageBox.confirm(`确定删除 ${row.name}？`,'确认删除');await deleteKubernetesObject({cluster_id:clusterID.value,resource:resource.value,namespace:row.namespace,name:row.name});load()}
watch(group,()=>{resource.value=group.value.resources[0].key},{immediate:true});watch([clusterID,resource,namespace,keyword],load);loadClusters().then(load)
const columns=computed<ColDef[]>(()=>[{headerName:'序号',valueGetter:(p:any)=>p.node.rowIndex+1,width:70},{field:'namespace',headerName:'命名空间',hide:!current.value.namespaced,minWidth:140},{field:'name',headerName:'名称',minWidth:220,flex:1},{field:'kind',headerName:'类型',minWidth:130},{field:'status',headerName:'状态',minWidth:110},{field:'age',headerName:'存活时间',minWidth:100},{headerName:'操作',pinned:'right',width:150,cellRenderer:(p:any)=>{const w=document.createElement('div'),e=document.createElement('button'),d=document.createElement('button');w.className='actions';e.className='btn';e.textContent='编辑';e.onclick=()=>edit(p.data);d.className='btn danger';d.textContent='删除';d.onclick=()=>remove(p.data);w.append(e,d);return w}}])
</script>
<template><section class="page" :class="{'workload-page':String(route.meta.kubernetesGroup)==='workloads'}"><div class="toolbar"><div class="filters"><el-select v-model="clusterID" placeholder="选择集群"><el-option v-for="x in clusters" :key="x.id" :label="x.alias||x.name" :value="x.id"/></el-select><el-select v-model="resource"><el-option v-for="x in group.resources" :key="x.key" :label="x.label" :value="x.key"/></el-select><el-input v-if="current.namespaced" v-model="namespace" placeholder="命名空间（全部）" clearable/><el-input v-model="keyword" placeholder="输入即搜索" clearable/></div><el-button type="primary" @click="edit()">新建 YAML</el-button></div><AppDataGrid class="grid" :row-data="rows" :column-defs="columns" pagination/><el-dialog v-model="dialog" :title="`${group.label} · ${current.label}`" width="720px"><el-input v-model="yaml" type="textarea" :rows="22" class="yaml"/><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></section></template>
<style scoped>.page{height:100%;display:flex;flex-direction:column;gap:10px;min-width:0;min-height:0}.workload-page{gap:2px}.workload-page .toolbar{padding-block:4px}.toolbar,.filters{display:flex;align-items:center;gap:8px}.toolbar{justify-content:space-between}.filters{min-width:0;flex-wrap:wrap}.filters .el-select{width:150px}.filters .el-input{width:170px}.grid{flex:1;min-height:0}.yaml :deep(textarea){font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11px}</style>
